'use strict';

// Parse a compact duration like "1h30m", "45m", "90s" into seconds.
const UNIT_SECONDS = { h: 3600, m: 60, s: 1 };

function parseDuration(text) {
  const match = /^(\d+)([hms])/.exec(String(text).trim());
  if (!match) throw new Error(`bad duration: ${text}`);
  const n = Number(match[1]);
  return match[2] === 'h' ? n * 60 : n * UNIT_SECONDS[match[2]];
}

module.exports = { parseDuration };

