'use strict';

// Parse a compact duration like "1h30m", "45m", "90s" into seconds.
const UNIT_SECONDS = { h: 3600, m: 60, s: 1 };

function parseDuration(text) {
  const parts = String(text).trim().match(/(\d+)([hms])/g);
  if (!parts) throw new Error(`bad duration: ${text}`);
  return parts.reduce((sum, part) => {
    const match = /(\d+)([hms])/.exec(part);
    const n = Number(match[1]);
    return sum + n * UNIT_SECONDS[match[2]];
  }, 0);
}

module.exports = { parseDuration };
